import 'package:dio/dio.dart';
import '../../../core/networking/player_api_client.dart';
class SecurityApi { final PlayerApiClient client; const SecurityApi(this.client); Future<Map<String,dynamic>> overview() async { final r=await client.get('/security/overview'); final b=Map<String,dynamic>.from(r.data as Map); if(b['ok']!=true) throw DioException(requestOptions:r.requestOptions,response:r,message:'Security overview failed'); return Map<String,dynamic>.from(b['data'] as Map); } Future<int> revokeOtherSessions() async { final r=await client.post('/security/sessions/revoke-others',data:const {}); final b=Map<String,dynamic>.from(r.data as Map); if(b['ok']!=true) throw DioException(requestOptions:r.requestOptions,response:r,message:'Session revocation failed'); final d=Map<String,dynamic>.from(b['data'] as Map); return (d['revokedCount'] as num? ?? 0).toInt(); } }
